parameters.jsCode:
const operators = Array.isArray($json.items) ? $json.items : [];

const alert = {
  alert_type: $('Recuperar Alarma').item.json.alert_type,
  attack_phase: $('Recuperar Alarma').item.json.attack_phase,
  severity: Number($('Recuperar Alarma').item.json.severity),
  is_business_hours: Boolean($('Recuperar Alarma').item.json.is_business_hours),
};

function arr(x) { return Array.isArray(x) ? x : []; }

function activeCount(o) {
  // Usa una sola métrica; aquí priorizo active_assigned
  if (typeof o.active_assigned === 'number') return o.active_assigned;
  if (typeof o.currentAlarmsCount === 'number') return o.currentAlarmsCount;
  return 0;
}

function hasSkill(o, key, value) {
  const list = arr(o.skills?.[key]);
  return list.includes(value);
}

const candidates = operators
  .filter(o => o.is_active === true)
  .filter(o => o.on_call === false)
  .filter(o => activeCount(o) < Number(o.max_active ?? 0)) // CAPACIDAD HARD
  .filter(o => !(o.business_hours_only === true && alert.is_business_hours === false)) // HORARIO HARD
  .filter(o => hasSkill(o, "alert_types", alert.alert_type)) // TIPO HARD
  .filter(o => hasSkill(o, "attack_phases", alert.attack_phase)) // FASE HARD
  .filter(o => alert.severity >= Number(o.skills?.min_severity ?? Infinity)) // SEVERIDAD HARD (opcional pero recomendado)
  .map(o => ({
    operator_id: o.operator_id,
    sla_ack_seconds: o.sla_ack_seconds,
    sla_resolve_seconds: o.sla_resolve_seconds,
    max_active: o.max_active,
    active_assigned: activeCount(o),
    business_hours_only: o.business_hours_only,
    skills: {
      min_severity: o.skills?.min_severity ?? null,
      alert_types: arr(o.skills?.alert_types),
      attack_phases: arr(o.skills?.attack_phases),
    },
  }));

return [{
  json: {
    alert,
    candidates,
    candidates_count: candidates.length,
  }
}];

